String reasonDescriptionKey(int reasonCode, String fallback) =>
    reasonCode != 0 && generatedReasonSymbolByCode.containsKey(reasonCode)
        ? 'std.reason.$reasonCode'
        : fallback;

String reasonActionKey(int reasonCode) =>
    generatedReasonHasOperatorAction.contains(reasonCode)
        ? 'std.reason.$reasonCode.action'
        : '';

String reasonConsequenceKey(int reasonCode) =>
    generatedReasonSymbolByCode.containsKey(reasonCode)
        ? 'std.reason.$reasonCode.consequence'
        : '';
